    "sec02_coverStory": {
      "sectionTitle": "BÀI ĐINH TRANG NHẤT · COVER STORY",
      "editorialHeadline": "Thông tư 50 mở khóa 183.000 tỷ đồng dư địa tín dụng giữa lúc tỷ giá trung tâm lập đỉnh 25.679 đồng và khối ngoại xả ròng kỷ lục",
      "editorialSubheadline": "Phiên 25/11/2026 chứng kiến bước ngoặt thanh khoản ngân hàng khi trần LDR chuẩn bị tăng lên 95%, trong khi VN-Index đánh mất mốc 1.700 điểm dưới sức ép bán ròng gần 5.700 tỷ đồng.",
      "dek": "Từ ngày 1/12/2026, Thông tư 50/2026/TT-NHNN nâng trần tỷ lệ cho vay trên tiền gửi từ 85% lên 95%, tạo dư địa tăng thêm 183.000 tỷ đồng tín dụng tại 26 ngân hàng trong mùa cao điểm cuối năm.",
      "executiveSummary": "Thông tư 50/2026/TT-NHNN hiệu lực từ ngày 1/12 nâng trần LDR từ 85% lên 95%, mở rộng dư địa cho vay thêm 183.000 tỷ đồng tại 26 ngân hàng. Trong ngày 25/11, tỷ giá trung tâm lập kỷ lục 25.679 VND/USD nhưng giá bán ngân hàng hạ dưới 26.000 đồng. Cùng phiên, VN-Index giảm về 1.687,45 điểm.",
      "leadArticle": {
        "headline": "Thông tư 50 sắp có hiệu lực, dư địa cho vay tại 26 ngân hàng tăng 183.000 tỷ đồng",
        "eventId": "EVT-10",
        "sourceName": "Tạp chí Người Quan Sát",
        "publishedAt": "25/11/2026 16:03 | Nguồn gốc: Tạp chí Người Quan Sát (2026-11-25T16:03:01+07:00)",
        "sourceUrl": "https://nguoiquansat.vn/thong-tu-50-sap-co-hieu-luc-du-dia-cho-vay-tai-26-ngan-hang-tang-183-000-ty-dong-330020.html",
        "summary": "Thông tư 50/2026/TT-NHNN hiệu lực từ ngày 1/12 nâng trần LDR từ 85% lên 95%, mở rộng dư địa cho vay thêm 183.000 tỷ đồng tại 26 ngân hàng. Trong ngày 25/11, tỷ giá trung tâm lập kỷ lục 25.679 VND/USD nhưng giá bán ngân hàng hạ dưới 26.000 đồng. Cùng phiên, VN-Index giảm về 1.687,45 điểm.",
        "supportingQuote": "Theo TCBS Research, BIDV, Vietcombank, MB, VPBank và Techcombank là những ngân hàng có dư địa cho vay tăng thêm nhiều nhất khi áp dụng Thông tư 50 với trần LDR nâng từ 85% lên 95%.",
        "imageUrl": "https://nqs.1cdn.vn/thumbs/1200x630/2026/11/25/ktck.1cdn.vn-2026-11-25-_sbv-1740386844547710867672.jpeg"
      },
      "imageUrl": "https://nqs.1cdn.vn/thumbs/1200x630/2026/11/25/ktck.1cdn.vn-2026-11-25-_sbv-1740386844547710867672.jpeg",
      "supportingQuote": "Theo TCBS Research, BIDV, Vietcombank, MB, VPBank và Techcombank là những ngân hàng có dư địa cho vay tăng thêm nhiều nhất khi áp dụng Thông tư 50 với trần LDR nâng từ 85% lên 95%.",
      "editorialPullQuote": "Theo TCBS Research, BIDV, Vietcombank, MB, VPBank và Techcombank là những ngân hàng có dư địa cho vay tăng thêm nhiều nhất khi áp dụng Thông tư 50 với trần LDR nâng từ 85% lên 95%.",
      "pullQuote": "Theo TCBS Research, BIDV, Vietcombank, MB, VPBank và Techcombank là những ngân hàng có dư địa cho vay tăng thêm nhiều nhất khi áp dụng Thông tư 50 với trần LDR nâng từ 85% lên 95%.",
      "editorialSynthesis": "Bốn chuyển động trọng yếu của phiên 25/11/2026 từ 40 bản tin xác minh 0–24h: (1) Nới room thanh khoản & tái định hình bộ máy ngân hàng: Thông tư 50/2026/TT-NHNN có hiệu lực từ 1/12 nâng trần LDR từ 85% lên 95% giúp 26 ngân hàng tăng thêm 183.000 tỷ đồng dư địa cho vay, Vietcombank mua lại trước hạn 1.550 tỷ đồng trái phiếu, GPBank lãi 1.064 tỷ đồng sau 9 tháng về tay VPBank, cùng loạt thay đổi lãnh đạo cấp cao tại SeABank, Agribank, SCB và LPBank; (2) Tỷ giá & lãi suất phân hóa trước dữ liệu PCE Mỹ: Tỷ giá trung tâm NHNN tăng 11 đồng lên đỉnh kỷ lục 25.679 VND/USD nhưng giá bán tại Vietcombank lùi về 25.970 đồng khi DXY dịu xuống 103,89 điểm, trong khi LPBank giảm 0,1–0,2 điểm % lãi suất tiền gửi các kỳ hạn phụ và Bac A Bank hạ lãi suất cho vay sản xuất kinh doanh; (3) Thị trường vốn rung lắc mạnh quanh ngưỡng 1.700 điểm: VN-Index không giữ được vùng 1.705 điểm trong phiên sáng và đóng cửa giảm 9,69 điểm (-0,57%) về 1.687,45 điểm khi khối ngoại bán ròng kỷ lục gần 5.700 tỷ đồng (riêng thỏa thuận VIC gần 4.600 tỷ đồng); (4) Chuyển đổi số & hàng hóa quốc tế: Chính phủ yêu cầu bộ ngành công khai bài toán AI cho doanh nghiệp Việt, hơn 50% lượng Bitcoin lưu hành rơi vào trạng thái thua lỗ và giá vàng thế giới đảo chiều giảm 2,6% xuống sát 3.550 USD/oz.",
      "marketImpact": "(1) Việc nâng trần LDR lên 95% từ đầu tháng 12 tạo nguồn lực tín dụng mới khoảng 183.000 tỷ đồng giúp các doanh nghiệp sản xuất và bán lẻ dễ tiếp cận vốn lưu động phục vụ mùa Tết 2027. (2) Lực bán ròng gần 5.700 tỷ đồng của khối ngoại cùng việc VN-Index lùi dưới 1.700 điểm giữ tâm lý nhà đầu tư cá nhân thận trọng, ưu tiên dòng tiền phòng thủ và các khoản gửi tiết kiệm 6,7–7,1%/năm. (3) Tỷ giá ngân hàng lùi dưới 26.000 đồng giảm bớt áp lực giá vốn nhập khẩu ngắn hạn nhưng rủi ro Fed tăng lãi suất 0,25 điểm % tháng 12 vẫn hiện hữu.",
      "fintechLensAction": "Khi 26 ngân hàng có thêm 183.000 tỷ đồng dư địa tín dụng và TP.HCM đẩy mạnh kết nối ngân hàng – doanh nghiệp cuối năm, Payoo thúc đẩy giải pháp SmartPOS tích hợp trả góp 0% và đối soát dòng tiền Virtual Account giúp hộ kinh doanh minh bạch doanh thu để tiếp cận vốn nhanh chóng.",
      "monitoringWatchpoint": "Theo dõi diễn biến áp dụng Thông tư 50 từ ngày 1/12, dòng vốn ngoại trên sàn HOSE sau phiên bán ròng kỷ lục 25/11 và chỉ số lạm phát PCE Mỹ tác động tới DXY.",
      "whyItMatters": "(1) Việc nâng trần LDR lên 95% từ đầu tháng 12 tạo nguồn lực tín dụng mới khoảng 183.000 tỷ đồng giúp các doanh nghiệp sản xuất và bán lẻ dễ tiếp cận vốn lưu động phục vụ mùa Tết 2027. (2) Lực bán ròng gần 5.700 tỷ đồng của khối ngoại cùng việc VN-Index lùi dưới 1.700 điểm giữ tâm lý nhà đầu tư cá nhân thận trọng, ưu tiên dòng tiền phòng thủ và các khoản gửi tiết kiệm 6,7–7,1%/năm. (3) Tỷ giá ngân hàng lùi dưới 26.000 đồng giảm bớt áp lực giá vốn nhập khẩu ngắn hạn nhưng rủi ro Fed tăng lãi suất 0,25 điểm % tháng 12 vẫn hiện hữu.",
      "keyMarketImplication": "Khi 26 ngân hàng có thêm 183.000 tỷ đồng dư địa tín dụng và TP.HCM đẩy mạnh kết nối ngân hàng – doanh nghiệp cuối năm, Payoo thúc đẩy giải pháp SmartPOS tích hợp trả góp 0% và đối soát dòng tiền Virtual Account giúp hộ kinh doanh minh bạch doanh thu để tiếp cận vốn nhanh chóng."
    },
